import type { Metadata } from 'next';
import type { ReactNode } from 'react';
import './globals.css';
import { fontVariables } from './fonts';
import Footer from '@/components/Footer';
import Header from '@/components/Header';
import { content, siteUrl } from '@/content';

// Generated by `npm run og` from the built hero headline.
const shareImage = { url: '/og/en.png', width: 1200, height: 630, alt: content.meta.title };

export const metadata: Metadata = {
  metadataBase: new URL(siteUrl),
  title: content.meta.title,
  description: content.meta.description,
  alternates: { canonical: '/' },
  openGraph: {
    type: 'website',
    siteName: 'Gelum Digital',
    url: '/',
    title: content.meta.title,
    description: content.meta.description,
    locale: 'en_AU',
    images: [shareImage],
  },
  twitter: {
    card: 'summary_large_image',
    title: content.meta.title,
    description: content.meta.description,
    images: [shareImage],
  },
};

/**
 * Marks `.reveal` sections visible once they enter the viewport (see globals.css).
 * Inline and dependency-free so it never waits on the JS bundle; without
 * IntersectionObserver it does nothing and every section is simply shown.
 */
const revealScript = `(function(){if(!('IntersectionObserver' in window))return;var d=document.documentElement;d.classList.add('js');document.addEventListener('DOMContentLoaded',function(){var io=new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('is-visible');io.unobserve(e.target);}});},{rootMargin:'0px 0px -10% 0px'});document.querySelectorAll('.reveal').forEach(function(el){io.observe(el);});});})();`;

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    // The inline script adds a class to <html> before hydration.
    <html lang="en-AU" className={fontVariables} suppressHydrationWarning>
      <body>
        {/* First in <body>: runs before any section is parsed or painted. */}
        <script dangerouslySetInnerHTML={{ __html: revealScript }} />
        <a
          href="#main"
          className="sr-only rounded-control bg-ink px-4 py-2 text-sm text-surface focus:not-sr-only focus:fixed focus:top-3 focus:left-3 focus:z-50"
        >
          {content.skipLink}
        </a>
        <Header />
        <main id="main" tabIndex={-1} className="focus:outline-none">
          {children}
        </main>
        <Footer />
      </body>
    </html>
  );
}
